<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { overview } from '../mock/seed.js'
import Icon from '../components/Icon.vue'
import MetricCard from '../components/MetricCard.vue'
import TrendChart from '../components/TrendChart.vue'
import RunTable from '../components/RunTable.vue'
defineProps({ envs: Array, snapshot: Object, presentation: Boolean })
const emit = defineEmits(['navigate', 'run', 'info', 'presentation'])
const version = ref('OS 24.03 RC2'), days = ref(7)
const stats = computed(() => overview(version.value, days.value))
const stages = [{ icon: 'code', label: '代码', system: 'Gerrit', value: '32 次变更', target: 'info' }, { icon: 'settings', label: '构建', system: 'Jenkins', value: '18 次构建', target: 'runs' }, { icon: 'box', label: '制品', system: 'JFrog', value: '6 个镜像', target: 'info' }, { icon: 'server', label: '环境', system: 'Argus', value: '24 个环境', target: 'environments' }, { icon: 'play', label: '执行', system: '测试框架', value: '128 次任务', target: 'runs' }, { icon: 'clipboard', label: '问题与回归', system: 'RDC', value: '12 项待回归', target: 'quality' }]
const activeStage = ref(0), chainPaused = ref(false)
let chainTimer
onMounted(() => { chainTimer = setInterval(() => { if (!chainPaused.value) activeStage.value = (activeStage.value + 1) % stages.length }, 2200) })
onBeforeUnmount(() => clearInterval(chainTimer))
const resourceGroups = [{ label: '可借用', states: ['available'], color: 'green' }, { label: '使用中', states: ['running', 'leased'], color: 'blue' }, { label: '待处理', states: ['maintenance', 'cleaning', 'reconciling', 'checking'], color: 'amber' }, { label: '隔离', states: ['isolated'], color: 'red' }]
</script>
<template>
  <div class="page-heading"><div><div class="eyebrow">TESTING INTELLIGENCE</div><h1>版本总览<span class="demo-tag">演示数据</span></h1><p>从环境准备到问题回归，度量每一个测试环节。</p></div><div class="heading-actions dashboard-actions"><select v-model="version" aria-label="版本范围"><option>OS 24.03 RC2</option><option>OS 24.03 RC1</option></select><select v-model="days" aria-label="统计周期"><option :value="7">最近 7 天</option><option :value="3">最近 3 天</option></select><button class="button secondary" @click="emit('info')"><Icon name="info" :size="16" />指标口径</button><button class="button outline" @click="emit('presentation')"><Icon :name="presentation ? 'shrink' : 'expand'" :size="17" />{{ presentation ? '退出大屏' : '大屏模式' }}</button></div></div>
  <div class="scope-line"><span><i class="dot teal" />版本历史样本</span> {{ version }}<span>·</span>最近 {{ days }} 天<span>·</span>{{ stats.total.toLocaleString() }} 次用例执行<span class="scope-date">截至 2026-10-30</span></div>
  <div class="metrics-grid dashboard-metrics"><MetricCard label="测试通过率" :value="stats.rate + '%'" :detail="`${stats.passed.toLocaleString()} / ${stats.total.toLocaleString()} 次`" icon="shield" tone="teal" /><MetricCard label="执行任务" :value="stats.runs" detail="所选范围内运行次数" icon="clipboard" /><MetricCard label="环境利用率" :value="stats.utilization + '%'" detail="7 天固定样本 · 时间加权" icon="server" tone="teal" /><MetricCard label="准备耗时 P50" :value="stats.prepare" unit="min" detail="7 天固定样本 · 设备就绪" icon="clock" /><MetricCard label="证据完整率" :value="stats.evidence + '%'" detail="7 天固定样本 · 五项证据" icon="clipboard" tone="teal" /><MetricCard label="待回归问题" :value="stats.pending" detail="版本问题快照 · 不随周期变化" icon="alert" tone="amber" /></div>
  <section class="panel chain-panel"><div class="panel-heading"><h2>版本验证链路</h2><span class="subtle-note chain-live"><i></i>全流程追溯 · 当前节点 <b>{{ stages[activeStage].label }} · {{ stages[activeStage].system }}</b></span></div><div class="pipeline-chain" @mouseenter="chainPaused = true" @mouseleave="chainPaused = false"><template v-for="(stage, i) in stages" :key="stage.label"><button class="pipeline-stage" :class="{ 'is-done': activeStage > i, 'is-active': activeStage === i }" :aria-current="activeStage === i ? 'step' : undefined" @click="stage.target === 'info' ? emit('info') : emit('navigate', stage.target)"><span v-if="activeStage === i" class="stage-current">当前</span><span class="stage-icon"><Icon :name="stage.icon" :size="24" /></span><span><strong>{{ stage.label }}</strong><small>{{ stage.system }}</small><b>{{ stage.system === 'Argus' ? `${envs.length} 个环境` : stage.system === '测试框架' ? '128 次任务' : stage.value }}</b></span></button><span v-if="i < stages.length - 1" class="chain-link" :class="activeStage > i ? 'is-passed' : activeStage === i + 1 ? 'is-flowing' : ''"><i class="link-track"></i><i class="link-fill"></i><i v-if="activeStage === i + 1" class="link-pulse"></i></span></template></div><div class="subtle-note chain-note"><i class="dot teal" />接入目标示意 · 固定演示链路，不随上方统计范围变化 · 节点按流程自动轮播，非实时系统状态</div></section>
  <div class="analytics-grid"><section class="panel chart-panel"><div class="panel-heading"><h2>执行趋势</h2><span class="subtle-note">{{ version }} · 最近 {{ days }} 天</span></div><TrendChart :points="stats.points" /></section><section class="panel resource-overview"><div class="panel-heading"><h2>环境资源</h2><button class="text-button" @click="emit('navigate', 'environments')">详情<Icon name="chevron" :size="14" /></button></div><div class="resource-total mono">{{ envs.length }}<small>个环境 <span>· 当前快照</span></small></div><div class="stacked-bar large"><i v-for="group in resourceGroups" :key="group.label" :class="`bg-${group.color}`" :style="{ width: envs.filter(e => group.states.includes(e.status)).length / (envs.length || 1) * 100 + '%' }" /></div><div class="resource-legend-row" v-for="group in resourceGroups" :key="group.label"><span><i class="dot" :class="group.color" />{{ group.label }}</span><strong class="mono">{{ envs.filter(e => group.states.includes(e.status)).length }}</strong><span class="mono">{{ (envs.filter(e => group.states.includes(e.status)).length / (envs.length || 1) * 100).toFixed(1) }}%</span></div></section><section class="panel failure-panel"><div class="panel-heading"><h2>失败原因分布</h2></div><p class="subtle-note">本期 {{ stats.total - stats.passed }} 次未通过用例</p><div class="failure-row" v-for="item in stats.failures" :key="item.label"><span>{{ item.label }}</span><div class="failure-track"><i :class="`bg-${item.tone}`" :style="{ width: item.count / Math.max(...stats.failures.map(f => f.count), 1) * 100 + '%' }" /></div><strong class="mono">{{ item.count }}</strong></div><button class="text-button align-right" @click="emit('navigate', 'quality')">查看明细<Icon name="chevron" :size="14" /></button></section></div>
  <div class="dashboard-bottom"><section class="panel recent-runs"><div class="panel-heading"><h2>近期执行</h2><button class="text-button" @click="emit('navigate', 'runs')">查看全部<Icon name="chevron" :size="14" /></button></div><RunTable :runs="version.endsWith('RC2') ? snapshot.runs.slice(0, 3) : []" compact @select="emit('run', $event)" /></section><section class="panel attention-panel"><div class="panel-heading"><h2>需要关注</h2><span class="count-pill">当前快照</span></div><button class="attention-item" @click="emit('navigate', 'maintenance')"><span class="soft-icon tone-red"><Icon name="shield" :size="19" /></span><span><strong>共享设备健康复核</strong><small>维护和隔离设备需复核后恢复可用</small></span><Icon name="chevron" :size="16" /></button><button class="attention-item" @click="emit('navigate', 'runs')"><span class="soft-icon tone-amber"><Icon name="clipboard" :size="19" /></span><span><strong>{{ snapshot.runs.filter(r => r.status === 'reconciling').length }} 个任务待对账</strong><small>确认任务终态后，进入清理与释放</small></span><Icon name="chevron" :size="16" /></button><button class="attention-item" @click="emit('navigate', 'quality')"><span class="soft-icon tone-blue"><Icon name="refresh" :size="19" /></span><span><strong>问题修复与回归</strong><small>关联版本、执行证据和问题记录</small></span><Icon name="chevron" :size="16" /></button></section></div>
</template>
